from domain import view

class API:
    def __init__(self, store):
        self.store = store

    def list(self, owner):
        return 200, [view(x) for x in self.store.owned(owner)]

    def page(self, owner, limit=2, cursor=None):
        if isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= 5:
            return 400, {'error': 'limit must be an integer from 1 to 5'}
        if cursor is not None and not isinstance(cursor, str):
            return 400, {'error': 'cursor must be a string or null'}
        rows = [x for x in self.store.owned(owner)
                if cursor is None or x.id > cursor]
        items = rows[:limit]
        next_cursor = items[-1].id if len(rows) > limit else None
        return 200, {'items': [view(x) for x in items], 'next_cursor': next_cursor}

