class Client:
    def __init__(self, api, owner):
        self.api, self.owner = api, owner

    def items(self):
        status, body = self.api.list(self.owner)
        if status != 200:
            raise ValueError(status)
        return body

    def iter_items(self, limit=2):
        cursor = None
        while True:
            status, body = self.api.page(self.owner, limit=limit, cursor=cursor)
            if status != 200:
                raise ValueError(status)
            yield from body['items']
            cursor = body['next_cursor']
            if cursor is None:
                return

