import pytest

from api import API
from client import Client
from domain import Item
from store import Store


def test_pages_filter_sort_and_boundaries():
    api = API(Store([Item(i, owner, i) for i, owner in
                     [('d', 'u'), ('b', 'v'), ('c', 'u'), ('a', 'u')]]))
    assert api.page('u') == (200, {
        'items': [{'id': 'a', 'text': 'a'}, {'id': 'c', 'text': 'c'}],
        'next_cursor': 'c',
    })
    assert api.page('u', cursor='b')[1] == {
        'items': [{'id': 'c', 'text': 'c'}, {'id': 'd', 'text': 'd'}],
        'next_cursor': None,
    }
    for owner, cursor in [('u', 'z'), ('missing', None)]:
        assert api.page(owner, cursor=cursor) == (200, {'items': [], 'next_cursor': None})


def test_empty_cursor_and_live_insertions():
    store = Store([Item(i, 'u', i) for i in ['', 'b', 'd']])
    api = API(store)
    assert api.page('u', 1)[1]['next_cursor'] == ''
    assert api.page('u', 1, '')[1]['items'] == [{'id': 'b', 'text': 'b'}]
    iterator = Client(api, 'u').iter_items(limit=1)
    assert next(iterator)['id'] == ''
    assert next(iterator)['id'] == 'b'
    store.add(Item('a', 'u', 'a'))
    store.add(Item('c', 'u', 'c'))
    assert [x['id'] for x in iterator] == ['c', 'd']
    assert Client(api, 'u').items() == list(Client(api, 'u').iter_items())


@pytest.mark.parametrize('limit', [True, False, 0, 6, -1, 2.0, '2', None])
def test_invalid_limits(limit):
    status, body = API(Store([])).page('u', limit=limit)
    assert status == 400
    assert 'error' in body


@pytest.mark.parametrize('cursor', [False, 0, 1.0, [], {}])
def test_invalid_cursors(cursor):
    status, body = API(Store([])).page('u', cursor=cursor)
    assert status == 400
    assert 'error' in body


def test_client_propagates_later_page_errors():
    class FailingAPI:
        def page(self, owner, limit, cursor):
            if cursor is None:
                return 200, {'items': [{'id': 'a', 'text': 'A'}], 'next_cursor': 'a'}
            return 503, {'error': 'unavailable'}

    iterator = Client(FailingAPI(), 'u').iter_items()
    assert next(iterator) == {'id': 'a', 'text': 'A'}
    with pytest.raises(ValueError) as error:
        next(iterator)
    assert error.value.args == (503,)


@pytest.mark.parametrize('limit', range(1, 6))
def test_valid_limits(limit):
    api = API(Store([Item(str(i), 'u', str(i)) for i in range(9)]))
    assert len(api.page('u', limit)[1]['items']) == limit
    assert list(Client(api, 'u').iter_items(limit)) == api.list('u')[1]
